create table recall_case (id uuid primary key, organization_id uuid not null references organization(id) on delete cascade, source_lot_id uuid not null references inventory_lot(id), title varchar(180) not null, status varchar(30) not null, created_at timestamp with time zone not null, created_by uuid not null references app_user(id));
create table recall_impact_snapshot (id uuid primary key, recall_case_id uuid not null references recall_case(id) on delete cascade, production_batch_id uuid not null references production_batch(id), location_id uuid not null references location(id), product_name varchar(180) not null, batch_number varchar(120) not null, affected_quantity numeric(19,3) not null, captured_at timestamp with time zone not null);
create index idx_recall_case_org on recall_case(organization_id,created_at);
